/* Original material atlas embedded so the local file preview works offline. */
const materialAtlas = new Image();
const materialTiles = {};
const materialsReady = new Promise(resolve => {
  materialAtlas.onload = () => {
    for (const [name,x,y] of [['asphalt',0,0],['paint',1,0],['wood',0,1],['steel',1,1]]) {
      const tile = document.createElement('canvas');
      tile.width = tile.height = 256;
      const w=materialAtlas.width/2, h=materialAtlas.height/2;
      tile.getContext('2d').drawImage(materialAtlas,x*w+8,y*h+8,w-16,h-16,0,0,256,256);
      materialTiles[name] = tile;
    }
    resolve();
  };
  materialAtlas.onerror = resolve;
});
materialAtlas.src = 'data:image/jpeg;base64,';
